INSERT INTO "Game" ("id", "slug", "title", "description", "ageLabel", "emoji", "color", "html", "fullHeight", "free", "published", "order", "updatedAt")
VALUES ('game_libro_tecnito', 'tecnito-y-sus-3-superpoderes', $TF$Tecnito y sus 3 superpoderes$TF$, $TF$Libro interactivo para niñas y niños de 3 a 6 años: Tecnito enseña sus tres superpoderes para cuidarse dentro y fuera de las pantallas, ¡Pregunto!, ¡Paro! y ¡Cuento! Se toca a los personajes para que se muevan y se lee en familia. Al final trae consejos para los adultos.$TF$, '3 a 6 años · libro interactivo', '📖', '#3DAEE3',
        $TF$<!doctype html>
<html lang="es">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<title>Tecnito y sus 3 superpoderes | Tecnofamilias</title>
<link rel="icon" type="image/png" href="data:image/png;base64,">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Fredoka:wght@500;600;700&family=Nunito:wght@600;700;800&display=swap">
<style>
:root{
  --stage-a:#F1F8FD; --stage-b:#D5E9F6;
  --ink:#283A5F; --ink-soft:#46587A;
  --ctrl:#FFFFFF; --ctrl-ink:#283A5F; --ctrl-line:rgba(40,58,95,.16); --ctrl-hover:#EEF6FC;
  --track:rgba(40,58,95,.14); --fill:#3DAEE4;
  --book-shadow:rgba(24,38,68,.32); --focus:#3DAEE4;
  --dur:900ms;
  color-scheme:light;
}
@media (prefers-color-scheme: dark){
  :root{
    --stage-a:#1E2C4C; --stage-b:#111A2F;
    --ink:#EEF3FA; --ink-soft:#B9C6DA;
    --ctrl:#24355B; --ctrl-ink:#F3F7FC; --ctrl-line:rgba(255,255,255,.16); --ctrl-hover:#2D4170;
    --track:rgba(255,255,255,.16); --fill:#3DAEE4;
    --book-shadow:rgba(0,0,0,.62);
    color-scheme:dark;
  }
}
@media (prefers-reduced-motion: reduce){ :root{ --dur:240ms; } }
*{box-sizing:border-box}
html,body{height:100%;margin:0}
body{background:var(--stage-b);color:var(--ink);font-family:'Nunito','Trebuchet MS','Segoe UI',sans-serif;-webkit-font-smoothing:antialiased}
.app{height:100%;display:flex;flex-direction:column;overflow:hidden;
  background:radial-gradient(ellipse 80% 70% at 50% 48%, var(--stage-a), var(--stage-b));
  padding:env(safe-area-inset-top,0px) env(safe-area-inset-right,0px) env(safe-area-inset-bottom,0px) env(safe-area-inset-left,0px)}
.bar{flex:none;display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px 20px}
.brand{display:flex;align-items:center;gap:10px;min-width:0;font-family:'Fredoka','Nunito',sans-serif;font-weight:600;font-size:18px}
.brand .t{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dots{display:inline-flex;gap:4px;flex:none}
.dots i{display:block;width:10px;height:10px;border-radius:50%}
.dots i:nth-child(1){background:#FDBE2F}.dots i:nth-child(2){background:#EF4A37}.dots i:nth-child(3){background:#3DAEE4}
.tools{display:flex;gap:8px;flex:none}
button{font:inherit;color:inherit}
.icon-btn,.nav-btn{border:1px solid var(--ctrl-line);background:var(--ctrl);color:var(--ctrl-ink);cursor:pointer;
  box-shadow:0 2px 0 var(--ctrl-line);transition:background-color .15s, transform .15s}
.icon-btn{width:44px;height:44px;border-radius:22px;display:grid;place-items:center;padding:0}
.icon-btn:hover,.nav-btn:hover:not(:disabled){background:var(--ctrl-hover)}
.icon-btn:active,.nav-btn:active:not(:disabled){transform:translateY(1px)}
.icon-btn[aria-pressed="false"] .i-on,.icon-btn[aria-pressed="true"] .i-off{display:none}
.nav-btn{height:48px;padding:0 20px;border-radius:24px;display:inline-flex;align-items:center;gap:8px;
  font-family:'Fredoka','Nunito',sans-serif;font-weight:600;font-size:17px;flex:none}
.nav-btn:disabled{opacity:.38;cursor:default}
:focus-visible{outline:3px solid var(--focus);outline-offset:3px}
.stage{flex:1;min-height:0;position:relative;display:flex;align-items:center;justify-content:center;
  touch-action:pan-y;user-select:none;-webkit-user-select:none;-webkit-tap-highlight-color:transparent}
.book{position:relative;perspective:2800px;transition:transform calc(var(--dur) * .8) cubic-bezier(.645,.045,.355,1)}
.book.instant,.book.instant .leaf{transition:none !important}
.base{position:absolute;top:0;background:#FBFAF6;border-radius:2px;display:none}
.leaf{position:absolute;top:0;transform-origin:0 50%;transform-style:preserve-3d;-webkit-transform-style:preserve-3d;
  transition:transform var(--dur) cubic-bezier(.645,.045,.355,1)}
.leaf.turned{transform:rotateY(-180deg)}
.leaf.peek:not(.turned){transform:rotateY(-16deg);transition-duration:.35s}
.face{position:absolute;inset:0;overflow:hidden;background:#FFFFFF;
  backface-visibility:hidden;-webkit-backface-visibility:hidden}
.face.back{transform:rotateY(180deg)}
.face.blank{background:#F8F5EE}
.pg-scale{position:absolute;left:0;top:0;width:1056px;height:816px;transform-origin:0 0;transform:scale(var(--s,1))}
.pg{display:block;width:1056px;height:816px}
.gutter,.turnshade{position:absolute;inset:0;pointer-events:none}
.front .gutter{background:linear-gradient(to right,rgba(20,30,50,.24),rgba(20,30,50,.07) 2.5%,rgba(20,30,50,0) 7%)}
.back .gutter{background:linear-gradient(to left,rgba(20,30,50,.24),rgba(20,30,50,.07) 2.5%,rgba(20,30,50,0) 7%)}
.single .front .gutter{background:linear-gradient(to right,rgba(20,30,50,.14),rgba(20,30,50,0) 4%)}
.turnshade{opacity:0}
.front .turnshade{background:linear-gradient(to left,rgba(20,30,50,.38),rgba(20,30,50,.08) 60%,rgba(255,255,255,.12))}
.back .turnshade{background:linear-gradient(to right,rgba(20,30,50,.38),rgba(20,30,50,.08) 60%,rgba(255,255,255,.12))}
.leaf.flipping .turnshade{animation:shade var(--dur) ease-in-out}
@keyframes shade{0%{opacity:0}50%{opacity:1}100%{opacity:0}}
.corner{position:absolute;right:0;bottom:0;width:18%;height:22%;z-index:2;cursor:pointer}
/* Interactividad */
.tap,[data-paint],[data-pstroke]{cursor:pointer}
.tap{transform-box:fill-box;transform-origin:50% 100%}
.tap.oc{transform-origin:50% 50%}
.fx-jump{animation:jump .7s ease-out}
.fx-bounce{animation:bounce .9s ease-out}
.fx-wiggle{animation:wiggle .7s ease-in-out}
.fx-pop{animation:pop .5s ease-out}
.fx-hug{animation:hug .7s ease-in-out}
.fx-spin{animation:spin .8s ease-in-out}
.fx-float{animation:float 1.2s ease-in-out}
.fx-shake{animation:shake .5s ease-in-out}
.fx-ring{animation:ring .7s linear}
.hello{animation:hello .8s ease-in-out}
@keyframes jump{0%{transform:none}15%{transform:scale(1.06,.9)}45%{transform:translateY(-16%) scale(.95,1.06)}70%{transform:translateY(0) scale(1.04,.96)}85%{transform:translateY(-3%)}100%{transform:none}}
@keyframes bounce{0%,100%{transform:none}30%{transform:translateY(-110%)}50%{transform:translateY(0) scale(1.15,.85)}70%{transform:translateY(-40%)}85%{transform:translateY(0)}}
@keyframes wiggle{0%,100%{transform:none}20%{transform:rotate(-7deg)}40%{transform:rotate(6deg)}60%{transform:rotate(-4deg)}80%{transform:rotate(2deg)}}
@keyframes pop{0%,100%{transform:none}40%{transform:scale(1.22)}70%{transform:scale(.94)}}
@keyframes hug{0%,100%{transform:none}35%{transform:scale(1.05,.95)}65%{transform:scale(.98,1.03)}}
@keyframes spin{0%{transform:none}100%{transform:rotate(360deg)}}
@keyframes float{0%{transform:none}55%{transform:translateY(-90%) scale(1.3)}100%{transform:none}}
@keyframes shake{0%,100%{transform:none}15%,55%{transform:translateX(-6%)}35%,75%{transform:translateX(6%)}}
@keyframes ring{0%,100%{transform:none}10%,30%,50%,70%{transform:rotate(-12deg)}20%,40%,60%,80%{transform:rotate(12deg)}}
@keyframes hello{0%,100%{transform:none}30%{transform:rotate(-3deg) scale(1.04)}60%{transform:rotate(2deg)}}
.pg .reveal{opacity:0;transition:opacity .25s;pointer-events:none}
.pg .reveal.show{opacity:1}
.msg-body,.msg-done{transition:opacity .35s}
.msg-done{opacity:0;pointer-events:none}
.msg-closed .msg-body{opacity:0}
.msg-closed .msg-done{opacity:1}
.dim{opacity:0;transition:opacity .7s;pointer-events:none}
.lights-off .dim{opacity:.55}
.lamp-glow{transition:opacity .5s;pointer-events:none}
.lights-off .lamp-glow{opacity:0}
.zz{opacity:0;transition:opacity .8s;pointer-events:none}
.lights-off .zz{opacity:1}
.hint{position:absolute;left:50%;bottom:10px;transform:translateX(-50%);margin:0;padding:8px 16px;border-radius:18px;
  background:var(--ctrl);color:var(--ink-soft);border:1px solid var(--ctrl-line);font-weight:700;font-size:14px;line-height:1.35;
  width:max-content;max-width:calc(100% - 32px);text-align:center;pointer-events:none;transition:opacity .5s;z-index:2000}
.hint.hide{opacity:0}
.bottom{justify-content:center;gap:20px;padding-bottom:16px}
.where{flex:1;max-width:340px;min-width:120px;display:flex;flex-direction:column;align-items:center;gap:8px;
  font-family:'Fredoka','Nunito',sans-serif;font-weight:600;font-size:17px;text-align:center}
.progress{width:100%;height:6px;border-radius:3px;background:var(--track);overflow:hidden}
.progress div{height:100%;width:0;border-radius:3px;background:var(--fill);transition:width calc(var(--dur) * .8) ease}
.sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
@media (max-width:560px){
  .nav-btn span{display:none}
  .nav-btn{padding:0;width:48px;justify-content:center}
  .bar{padding:10px 14px}
  .brand{font-size:16px}
  .bottom{gap:14px}
}
</style>
