4" fill="#FFFFFF"></rect></g></svg><div style="position: absolute; left: 40px; top: 34px; display: flex; align-items: center; gap: 12px; background: #FFFFFF; border-radius: 999px; padding: 8px 26px 8px 8px; box-shadow: 0 4px 0 rgba(40, 58, 95, 0.14)"><svg class="tap oc" data-fx="spin" width="54" height="54" viewBox="0 0 100 100" aria-hidden="true" style="display: block; flex: none"><circle cx="50" cy="50" r="44" fill="#EF4A37" stroke="#FFFFFF" stroke-width="5.28"></circle><rect x="35.04" y="31.52" width="10.56" height="36.96" rx="3.52" fill="#FFFFFF"></rect><rect x="54.4" y="31.52" width="10.56" height="36.96" rx="3.52" fill="#FFFFFF"></rect></svg><div style="display: flex; flex-direction: column"><span style="font-family: 'Fredoka', 'Nunito', 'Trebuchet MS', sans-serif; font-weight: 600; font-size: 15px; letter-spacing: 0.1em; text-transform: uppercase; color: #5A6B8C">Superpoder 2</span><span style="font-family: 'Fredoka', 'Nunito', 'Trebuchet MS', sans-serif; font-weight: 700; font-size: 28px; line-height: 1.05; color: #283A5F">¡Paro!</span></div></div><div style="position: absolute; left: 600px; top: 58px; width: 340px; box-sizing: border-box; background: #FFFFFF; border: 4px solid #283A5F; border-radius: 28px; padding: 14px 22px 16px; font-family: 'Fredoka', 'Nunito', 'Trebuchet MS', sans-serif; font-weight: 600; font-size: 26px; line-height: 1.22; color: #283A5F; text-align: center; text-wrap: balance">¡Pausa! Hora de movernos.<div style="position: absolute; left: 258px; bottom: -17px; width: 26px; height: 26px; background: #FFFFFF; border-right: 4px solid #283A5F; border-bottom: 4px solid #283A5F; transform: rotate(45deg)"></div></div><div style="position: absolute; left: 44px; right: 44px; bottom: 36px; box-sizing: border-box; background: #FFFFFF; border-radius: 30px; padding: 24px 48px 26px 40px; box-shadow: 0 6px 0 rgba(40, 58, 95, 0.14)"><p style="margin: 0px; font-family: 'Nunito', 'Trebuchet MS', 'Segoe UI', sans-serif; font-size: 26px; line-height: 1.42; font-weight: 700; color: #283A5F; text-wrap: pretty">¡Tin, tin, tin! Suena el relojito y los ojitos de Sofi ya están cansados. Tecnito pone la mano así: “Cuando suena el relojito… <span style="background: #EF4A37; color: #FFFFFF; border-radius: 10px; padding: 0px 8px">¡paro!</span>”. La tablet descansa, y ellos parpadean, se estiran y saltan como canguros.</p><div style="position: absolute; right: 18px; top: -22px; width: 46px; height: 46px; border-radius: 23px; background: #283A5F; color: #FFFFFF; font-family: 'Fredoka', 'Nunito', 'Trebuchet MS', sans-serif; font-weight: 600; font-size: 21px; display: flex; align-items: center; justify-content: center">6</div></div></div></section>
<section class="pg" aria-label="Página 7"><div style="width: 1056px; height: 816px; position: relative; overflow: hidden; background: #E4F4FC; font-family: 'Nunito', 'Trebuchet MS', 'Segoe UI', sans-serif; color: #283A5F"><svg viewBox="0 0 1056 816" width="1056" height="816" style="position: absolute; left: 0px; top: 0px; display: block" role="img" aria-label="Llega un mensaje de alguien desconocido y Tecnito pone su mano de alto frente a la tablet"><rect x="0" y="0" width="1056" height="816" rx="0" fill="#E4F4FC"></rect><rect x="0" y="500" width="1056" height="316" rx="0" fill="#F6E2C0"></rect><rect x="0" y="494" width="1056" height="10" rx="0" fill="#EBCB9A"></rect><rect x="0" y="560" width="1056" height="3" rx="0" fill="#EBCB9A" opacity="0.6"></rect><rect x="0" y="650" width="1056" height="3" rx="0" fill="#EBCB9A" opacity="0.6"></rect><rect x="82" y="464" width="14" height="150" rx="5" fill="#B97E43"></rect><rect x="484" y="464" width="14" height="150" rx="5" fill="#B97E43"></rect><rect x="60" y="450" width="460" height="18" rx="9" fill="#E0A867"></rect><path d="M261,410 L329,410 L353,450 L237,450 Z" fill="#1F2D4A"></path><rect x="90" y="122" width="410" height="300" rx="24" fill="#283A5F"></rect><clipPath id="scr5"><rect x="106" y="138" width="378" height="268" rx="12"></rect></clipPath><rect x="106" y="138" width="378" height="268" rx="12" fill="#FFFFFF"></rect><g clip-path="url(#scr5)"><g transform="translate(106 138)"><rect x="0" y="0" width="378" height="268" rx="0" fill="#FFFFFF"></rect><rect x="0" y="0" width="378" height="46" rx="0" fill="#EEF2F8"></rect><text x="20" y="30" font-family="Fredoka, Nunito, Trebuchet MS, sans-serif" font-size="18" font-weight="600" fill="#283A5F" text-anchor="start">Mensajes</text><g class="tap oc" data-fx="pop" data-toggle="msg-closed" data-sound="click"><circle cx="348" cy="23" r="34" fill="#FFFFFF" opacity="0"></circle><circle cx="348" cy="23" r="14" fill="#EF4A37"></circle><polyline points="342,17 354,29" fill="none" stroke="#FFFFFF" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"></polyline><polyline points="354,17 342,29" fill="none" stroke="#FFFFFF" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"></polyline></g><g class="msg-body"><circle cx="44" cy="104" r="26" fill="#AEB6C4"></circle><text x="44" y="115" font-family="Fredoka, Nunito, Trebuchet MS, sans-serif" font-size="30" font-weight="700" fill="#FFFFFF" text-anchor="middle">?</text><rect x="82" y="72" width="266" height="98" rx="20" fill="#EEF2F8"></rect><text x="102" y="112" font-family="Fredoka, Nunito, Trebuchet MS, sans-serif" font-size="22" font-weight="600" fill="#283A5F" text-anchor="start">Hola, ¿jugamos?</text><text x="102" y="146" font-family="Fredoka, Nunito, Trebuchet MS, sans-serif" font-size="22" font-weight="600" fill="#283A5F" text-anchor="start">Es un secreto.</text></g><g class="msg-done"><circle cx="189" cy="104" r="32" fill="#4DB38A"></circle><path d="M175.0,104 L185.0,115 L204.0,92" fill="none" stroke="#FFFFFF" stroke-width="7" stroke-linecap="round" stroke-linejoin="round"></path><text x="189" y="170" font-family="Fredoka, Nunito, Trebuchet MS, sans-serif" font-size="22" font-weight="700" fill="#283A5F" text-anchor="middle">¡Mensaje cerrado!</text></g><rect x="16" y="210" width="346" height="40" rx="20" fill="#FFFFFF" stroke="#C9D2DF" stroke-width="2"></rect><text x="36" y="236" font-family="Fredoka, Nunito, Trebuchet MS, sans-serif" font-size="16" font-weight="600" fill="#7D8AA3" text-anchor="start">Escribe aquí…</text></g></g><circle cx="295" cy="130.5" r="3.5" fill="#5B6F95"></circle><g class="tap" data-fx="jump"><g transform="translate(880 566) scale(0.95 0.95)"><rect x="-28" y="-64" width="18" height="64" rx="9" fill="#C98B5E"></rect><rect x="10" y="-64" width="18" height="64" rx="9" fill="#C98B5E"></rect><ellipse cx="-20" cy="-6" rx="18" ry="9" fill="#EF4A37"></ellipse><ellipse cx="20" cy="-6" rx="18" ry="9" fill="#EF4A37"></ellipse><path d="M-34,-152 C-34,-170 -18,